(()=>{'use strict';const C=CalendarCore,KEY='form-fuel-calendar-v1',root=document.querySelector('#calendar'),today=()=>C.dayKey(new Date()),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let selected=today(),month=C.parse(selected),db={schema:1,schedules:[],targets:[],logs:{}},storageError='';
try{const raw=localStorage.getItem(KEY);if(raw){const v=JSON.parse(raw);if(v.schema!==1||!Array.isArray(v.schedules)||!Array.isArray(v.targets)||!v.logs||typeof v.logs!=='object')throw Error();db=v;}}catch{storageError='Calendar storage could not be read. Existing stored data has been left untouched.';}
let sourceCache=null;function source(){if(sourceCache)return sourceCache;try{return sourceCache=JSON.parse(localStorage.getItem('form-fuel-v1')||'{}')||{};}catch{return {};}}
function persist(next){if(storageError){toast(storageError);return false;}try{localStorage.setItem(KEY,JSON.stringify(next));db=next;document.dispatchEvent(new Event('calendar:changed'));return true;}catch{toast('Calendar changes could not be saved. Free browser storage and try again.');return false;}}
function sync(){const next=structuredClone(db),p=source().plan;let changed=false;
if(p){const target={calories:p.calories,protein:p.protein,carbs:p.carbs,fat:p.fat??null,weight:p.weight},latest=next.targets.at(-1);if(!latest||JSON.stringify(latest.values)!==JSON.stringify(target)){next.targets=next.targets.filter(t=>t.from!==today());next.targets.push({from:today(),values:target});changed=true;}}
try{const saved=JSON.parse(localStorage.getItem('form-fuel-routines-v1')||'null');if(saved&&RoutineBuilder.validateSaved(saved)){const signature=JSON.stringify([saved.profile,saved.variant]),latest=next.schedules.at(-1);if(!latest||latest.signature!==signature){const plan=RoutineBuilder.generate(saved.profile,saved.variant);if(plan.ok){next.schedules=next.schedules.filter(s=>s.from!==today());next.schedules.push({from:today(),signature,days:plan.plan.days});changed=true;}}}}catch{/* Existing routine remains untouched. */}
if(changed)persist(next);}
function targets(date){const v=C.versionAt(db.targets,date);return {values:v?.values||source().plan||null,historical:!!v};}
function dayData(date){const meals=source().meals||[],n=C.nutrition(meals,date),target=targets(date),states=['calories','protein','carbs'].map(k=>C.targetState(n[k],target.values?.[k],k,n.count>0));return {n,target,states,hit:states.every(s=>s.hit),planned:C.workoutAt(db.schedules,date),log:db.logs[date]};}
const fmt=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:1}),longDate=date=>C.parse(date).toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'});
root.innerHTML='<div class="section-heading"><div><span class="section-number">03 /</span><div class="section-heading-copy"><h2 id="calendarHeading">Your progress, day by day.</h2><p class="section-description">A place for your training plan, daily fuel and the work you put in.</p></div></div><button type="button" class="secondary" id="calendarExport">Export calendar ↓</button></div><div class="calendar-workspace"><div class="calendar-board"><div class="calendar-toolbar"><div><p class="eyebrow">YOUR TRAINING CALENDAR</p><h3 id="calendarMonth"></h3></div><div class="calendar-controls"><button type="button" id="previousMonth" aria-label="Previous month">‹</button><button type="button" id="calendarToday">Today</button><button type="button" id="nextMonth" aria-label="Next month">›</button></div></div><div class="calendar-weekdays" aria-hidden="true">'+['M','T','W','T','F','S','S'].map(d=>'<span>'+d+'</span>').join('')+'</div><div class="calendar-grid" id="calendarGrid" role="group" aria-label="Choose a day"></div><div class="calendar-legend"><span><i class="planned-dot"></i>Planned workout</span><span><i class="done-dot"></i>Completed</span><span><i class="meal-dot"></i>Meals logged</span><span>★ Nutrition targets hit</span></div><p class="calendar-note" id="calendarScheduleNote"></p></div><div class="calendar-detail" id="calendarDetail" aria-live="polite"></div></div>';
function render(){const data=C.monthDays(month.getFullYear(),month.getMonth());root.querySelector('#calendarMonth').textContent=month.toLocaleDateString(undefined,{month:'long',year:'numeric'});root.querySelector('#calendarGrid').innerHTML='<span class="calendar-blank" aria-hidden="true"></span>'.repeat(data.offset)+data.days.map(date=>{const d=dayData(date);return '<button type="button" class="calendar-day '+(date===selected?'selected ':'')+(date===today()?'is-today ':'')+(d.log?'completed':'')+'" data-date="'+date+'" aria-pressed="'+(date===selected)+'" '+(date===today()?'aria-current="date"':'')+' aria-label="'+escape(longDate(date)+(d.log?', completed '+d.log.workout.title:d.planned?', planned '+d.planned.title:', no planned workout')+(d.n.count?', meals logged':'')+(d.hit?', nutrition targets hit':''))+'"><strong>'+Number(date.slice(-2))+'</strong><span class="calendar-day-title">'+escape(d.log?.workout.title||d.planned?.title||'')+'</span><span class="calendar-day-dots">'+(d.log?'<i class="done-dot"></i>':d.planned?'<i class="planned-dot"></i>':'')+(d.n.count?'<i class="meal-dot"></i>':'')+(d.hit?'<b>★</b>':'')+'</span></button>';}).join('');root.querySelectorAll('[data-date]').forEach(b=>{b.onclick=()=>choose(b.dataset.date);b.onkeydown=e=>{const offsets={ArrowRight:1,ArrowLeft:-1,ArrowDown:7,ArrowUp:-7};if(e.key in offsets){e.preventDefault();const date=C.parse(b.dataset.date);date.setDate(date.getDate()+offsets[e.key]);choose(C.dayKey(date),true);}};});root.querySelector('#calendarScheduleNote').textContent=storageError|| (db.schedules.length?'Your saved routine repeats on its suggested weekdays. New routines apply from the day you save them; completed sessions keep their original details.':'Save a routine above to automatically add its training days. You can also log a workout on any past or present day.');renderDetail();}
function choose(date,focus=false){selected=date;month=C.parse(date);render();if(focus)root.querySelector('[data-date="'+date+'"]').focus();else if(innerWidth<=1100)root.querySelector('#calendarDetail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function renderDetail(){const d=dayData(selected),future=selected>today(),w=d.log?.workout||d.planned;root.querySelector('#calendarDetail').innerHTML='<p class="eyebrow">'+(selected===today()?'TODAY':future?'UPCOMING':'DAILY RECORD')+'</p><h3>'+escape(longDate(selected))+'</h3><div class="calendar-summary '+(d.hit?'hit':'')+'">'+(future?'Planned day · completion opens on this date':!d.n.count?'No meals logged for this day':d.hit?'All nutrition targets hit':!d.target.values?'Set nutrition targets to compare this day':'Nutrition targets not all hit')+'</div><div class="calendar-macros">'+['calories','protein','carbs'].map((k,i)=>'<div class="calendar-macro"><div><span>'+({calories:'Calories eaten',protein:'Protein',carbs:'Carbs'}[k])+'</span><b class="status-'+d.states[i].kind+'">'+d.states[i].label+'</b></div><strong>'+fmt(d.n[k])+' <small>'+(k==='calories'?'kcal':'g')+'</small></strong><span class="calendar-target">Target '+(d.target.values?fmt(d.target.values[k])+(k==='calories'?' kcal':' g'):'not set')+'</span><div class="calendar-mini-track"><i style="width:'+(d.target.values?.[k]?Math.min(100,d.n[k]/d.target.values[k]*100):0)+'%"></i></div></div>').join('')+'</div><p class="calendar-note">Calories and carbs: within ±5% of target. Protein: at least the target. Based on logged meals'+(d.target.historical?' and targets saved for this date.':'; compared with current targets because no historical target was recorded.')+'</p><div class="calendar-burn"><span>Workout calories burned</span><strong>'+(d.log?(d.log.burn===null?'Not estimated':fmt(d.log.burn)+' <small>kcal</small>'):'—')+'</strong><p>'+(d.log?(d.log.burn===null?'No body weight or calorie value was supplied.':d.log.mode==='manual'?'User-entered workout burn.':'Estimate from '+d.log.minutes+' minutes · '+d.log.weight+' kg · '+d.log.met+' MET.'):'Log a completed workout to record its burn.')+'</p></div><div class="calendar-workout"><div class="calendar-workout-title"><h4>'+escape(w?.title||'Rest day / no workout planned')+'</h4><span>'+(d.log?'Completed ✓':w?'Planned':'Open day')+'</span></div>'+(w?'<p>'+ (d.log?d.log.minutes:w.estimatedMinutes)+' min'+(d.log?' recorded':' estimated')+'</p><details><summary>Workout exercises'+(w.exercises?.length?' · '+w.exercises.length:'')+'</summary><ol>'+ (w.exercises||[]).map(e=>'<li><button type="button" class="routine-demo" data-demo="'+escape(e.id)+'" data-name="'+escape(e.name)+'">'+escape(e.name)+' ↗</button><small>'+e.sets+' sets × '+escape(e.reps)+' · '+e.rest+' sec rest</small></li>').join('')+'</ol></details>':'<p>Recovery counts too. If you trained today, record the session below.</p>')+(!future?'<button type="button" class="primary full" id="logCalendarWorkout">'+(d.log?'Edit completed workout':w?'Mark workout complete':'Log a workout')+'</button>':'')+(d.log?'<button type="button" class="text-button" id="undoCalendarWorkout">Undo completion</button>':'')+'</div><div class="calendar-detail-actions"><button type="button" class="secondary" id="calendarMeal">Log a meal for this day</button><button type="button" class="text-button" id="calendarJournal">View '+d.n.count+' meal'+(d.n.count===1?'':'s')+' in journal ↗</button></div><p class="calendar-note">Workout burn is separate from food targets and is not your total daily energy expenditure. Food targets already account for your activity setting.</p>';
root.querySelector('#logCalendarWorkout')?.addEventListener('click',openWorkout);root.querySelector('#undoCalendarWorkout')?.addEventListener('click',()=>{const next=structuredClone(db);delete next.logs[selected];if(persist(next)){render();toast('Completion removed. Your planned workout remains.');}});root.querySelector('#calendarMeal').onclick=()=>{document.querySelector('#journalDate').value=selected;renderJournal();window.chooseFuelDay?.(selected);openMeal();};root.querySelector('#calendarJournal').onclick=()=>{document.querySelector('#journalDate').value=selected;renderJournal();window.PagePanels?.open('journal');};document.dispatchEvent(new Event('calendar:render'));}
const modal=document.createElement('dialog');modal.id='workoutLogDialog';modal.innerHTML='<form id="workoutLogForm"><div class="dialog-heading"><div><p class="eyebrow">RECORD YOUR SESSION</p><h2>Workout complete</h2></div><button type="button" class="close" aria-label="Close workout log">×</button></div><p id="workoutLogDate"></p><label>Workout name<input name="title" maxlength="100" required></label><div class="form-grid"><label>Actual duration (minutes)<input name="minutes" type="number" min="1" max="360" required></label><label>Body weight (kg, optional)<input name="weight" type="number" min="35" max="250" step="0.1" placeholder="Needed for an estimate"></label></div><label>Session intensity<select name="met"><option value="3.5">General resistance training · 3.5 MET</option><option value="6">Vigorous resistance training · 6 MET</option></select></label><label>Calories from your tracker (optional)<input name="manual" type="number" min="0" max="5000" step="1" placeholder="Overrides the estimate"></label><div class="plan-preview" id="workoutBurnPreview" role="status"></div><p class="tiny">The estimate uses MET × 3.5 × weight (kg) ÷ 200 × minutes. It includes resting energy during the session and can differ substantially from actual burn. <a href="https://pacompendium.com/" target="_blank" rel="noopener">2024 Compendium ↗</a></p><button type="submit" class="primary full">Save completed workout ↗</button></form>';document.body.append(modal);const form=modal.querySelector('form');modal.querySelector('.close').onclick=()=>modal.close();let editingDate=null;
function previewBurn(){const manual=form.elements.manual.value.trim(),weight=Number(form.elements.weight.value),minutes=Number(form.elements.minutes.value),met=Number(form.elements.met.value);const value=manual!==''?Number(manual):C.burn(minutes,weight,met);modal.querySelector('#workoutBurnPreview').textContent=value===null?'Enter your weight for an estimate, or supply a tracker value. You can also save without a burn estimate.':(manual!==''?'Entered burn: ':'Estimated session burn: ')+fmt(value)+' kcal';return {burn:value,mode:manual!==''?'manual':'estimate',minutes,weight:weight||null,met};}
function openWorkout(){editingDate=selected;const d=dayData(selected),w=d.log?.workout||d.planned;form.reset();form.elements.title.value=w?.title||'Workout';form.elements.minutes.value=d.log?.minutes||w?.estimatedMinutes||30;form.elements.weight.value=d.log?.weight||source().plan?.weight||'';form.elements.met.value=d.log?.met||'3.5';form.elements.manual.value=d.log?.mode==='manual'?d.log.burn:'';modal.querySelector('#workoutLogDate').textContent=longDate(selected);previewBurn();modal.showModal();}
form.oninput=previewBurn;form.onchange=previewBurn;form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity()||editingDate>today())return;const values=previewBurn(),d=dayData(editingDate),title=form.elements.title.value.trim();if(!title)return;const workout=structuredClone(d.log?.workout||d.planned||{title,exercises:[],estimatedMinutes:values.minutes});workout.title=title;const next=structuredClone(db);next.logs[editingDate]={...values,workout,completedAt:new Date().toISOString()};if(persist(next)){modal.close();render();toast('Workout saved to '+longDate(editingDate)+'.');}};
root.querySelector('#previousMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1,12);render();};root.querySelector('#nextMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1,12);render();};root.querySelector('#calendarToday').onclick=()=>choose(today());root.querySelector('#calendarExport').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({app:'Form & Fuel calendar',exportedAt:new Date().toISOString(),...db},null,2)],{type:'application/json'}));a.download='form-fuel-calendar.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);};
document.addEventListener('fuel:changed',()=>{sourceCache=null;sync();render();});document.addEventListener('routine:saved',()=>{sync();render();toast('Routine saved and added to your calendar from today.');});addEventListener('storage',e=>{sourceCache=null;if(['form-fuel-v1','form-fuel-routines-v1'].includes(e.key)){sync();render();}else if(e.key===KEY){try{const next=JSON.parse(e.newValue);if(next?.schema===1&&Array.isArray(next.schedules)&&Array.isArray(next.targets)&&next.logs){db=next;render();}}catch{}}});let lastDate=today();setInterval(()=>{if(lastDate!==today()){lastDate=today();sync();render();}},60000);window.WorkoutCalendar={selectedDate:()=>selected,logWorkout:(date=today())=>{if(date>today())return;choose(date);openWorkout();}};sync();render();})();
